<?php declare(strict_types=1);
namespace FMonitor2\PilotHttp;

final class ProductionPrepareFormRenderer implements PrepareFormRenderer,CompatibilityPrepareFormRenderer
{
    public function render(HttpUser $user,array $f):string
    {
        $e=[PilotView::class,'e'];$id=$e($f['id']);$selected=$f['selected']??[];$selectedInstallers=\array_map('strval',$selected['installers']??[]);$engineer=$f['engineer']??null;
        $installerData='';foreach($f['installers']as$x){$value=(string)$x['tabId'];$tab=\str_pad($value,6,'0',STR_PAD_LEFT);$installerData.='<span data-id="'.$e($value).'" data-name="'.$e($x['fio']).'" data-tab="'.$e($tab).'" data-position="'.$e($x['position']).'" data-busy="'.$e($x['busyUntil']??'').'" data-selected="'.(\in_array($value,$selectedInstallers,true)?'1':'0').'"></span>';}
        $command=isset($f['csrfToken']);$canUpload=$command&&($f['canUploadOriginal']??false);$route='/pilot/objects/'.$id.'/assignment-order/prepare';$hidden=$command?'<input type="hidden" name="csrfToken" value="'.$e($f['csrfToken']).'"><input type="hidden" name="processRevision" value="'.$e($f['processRevision']).'">':'';
        $summary='<div class="fm2-order-object"><strong>Объект монтажа № '.$id.'</strong><span>'.$e($f['registrationNumber']).' · '.$e($f['address']).', подъезд '.$e($f['entrance']).'</span><small>Плановый период: '.PilotView::date($f['plannedStartDate']).' — '.PilotView::date($f['plannedFinishDate']).'</small></div>';
        $flash=$f['flash']??null;$notice=$flash?'<div class="fm2-alert" role="status"><a href="#'.($e($flash['field']??'form-errors')).'">'.$e($flash['message']).'</a></div>':'';
        $installers=$f['installers']===[]?'<div class="shlz-empty-state"><p>Нет допустимых монтажников.</p></div>':'<div class="fm2-picker fm2-installer-picker" data-installer-picker><div class="fm2-picker-selection" data-picker-selection><span class="fm2-picker-selection-empty">Монтажники ещё не выбраны</span></div><button class="shlz-button shlz-button--primary" type="button" popovertarget="installer-picker">Выбрать монтажников</button><div class="fm2-picker-dialog" id="installer-picker" popover><div class="fm2-picker-head"><div><h3>Выбор монтажников</h3><p>Поиск по ФИО или шестизначному табельному номеру</p></div><button class="fm2-picker-x" type="button" aria-label="Закрыть окно" popovertarget="installer-picker" popovertargetaction="hide">×</button></div><div class="fm2-picker-modal-selection"><strong>Выбрано</strong><div class="fm2-picker-selection" data-picker-modal-selection><span class="fm2-picker-selection-empty">Пока никого</span></div></div><label class="fm2-search-field"><span class="fm2-visually-hidden">Поиск монтажника</span><input type="search" data-picker-search placeholder="Фамилия или табельный номер" autocomplete="off" autofocus></label><div class="fm2-picker-result-meta" data-picker-meta>Введите минимум 2 символа</div><div class="fm2-picker-results" data-picker-results aria-live="polite" aria-label="Результаты поиска"></div><footer class="fm2-picker-footer"><span data-picker-count>Выбрано: 0</span><button class="shlz-button shlz-button--primary shlz-button--sm" type="button" popovertarget="installer-picker" popovertargetaction="hide">Готово</button></footer></div><template data-picker-data>'.$installerData.'</template><div data-picker-inputs></div></div>';
        $engineerInfo=$engineer===null?'<div class="shlz-empty-state"><p>Инженер не назначен. Вернитесь в карточку объекта.</p></div>':'<div class="fm2-reference-person"><span class="shlz-avatar shlz-avatar--32" aria-hidden="true">'.PilotView::initials($engineer['fio']).'</span><span><strong>'.$e($engineer['fio']).'</strong><small>'.$e($engineer['position']).' · справочно из карточки объекта</small></span></div>';
        $uploadAction=$command&&$canUpload&&$f['installers']!==[]&&$engineer!==null?'<button class="shlz-button shlz-button--primary fm2-submit" type="submit" name="intent" value="upload">Загрузить распоряжение</button>':'';
        $templateAction=$command&&$f['installers']!==[]&&$engineer!==null?'<button class="shlz-button" type="submit" name="intent" value="template" formtarget="_blank" formnovalidate>Сформировать шаблон</button>':'';
        $upload=$canUpload?'<section class="fm2-order-upload" aria-labelledby="signed-original"><div class="fm2-order-section-head"><div><span class="fm2-order-eyebrow">Шаг 1</span><h2 id="signed-original">Подписанный оригинал</h2><p>Загрузите распоряжение в формате PDF.</p></div><span class="shlz-status shlz-status--blue">Обязательно</span></div><label class="fm2-file-drop" data-file-drop><input id="signedOriginal" type="file" name="signedOriginal" accept="application/pdf,.pdf" required data-file-input><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V4m0 0L7.5 8.5M12 4l4.5 4.5M5 14v5h14v-5"/></svg><span><strong><u>Выберите</u> или перетащите сюда файл</strong><small data-file-name>PDF, не более 25 МБ</small></span></label></section>':'';
        $helper='<aside class="fm2-order-helper"><div class="fm2-order-helper-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M7 3h7l4 4v14H7V3Zm7 0v5h4M10 13h5m-5 4h5"/></svg></div><div><span class="fm2-order-eyebrow">Если документа ещё нет</span><h2>Нужен шаблон?</h2><p>Сформируем PDF с выбранным составом и откроем его в новой вкладке. Это не обязательный шаг.</p></div>'.$templateAction.'</aside>';
        $changing=$f['changing']??false;$title=$changing?'Изменить состав монтажников':'Загрузить распоряжение';$intro=$changing?'Выберите полный новый состав. Предыдущее распоряжение и история закреплений сохранятся.':'Укажите состав и прикрепите подписанный оригинал.';
        $body='<div class="fm2-page-header fm2-order-heading"><div><h1>'.$title.'</h1><p>'.$intro.'</p></div></div>'.$notice.'<form id="form-errors" class="fm2-order-form" method="'.($command?'post':'get').'" action="'.$route.'"'.($command?' enctype="multipart/form-data"':'').'>'.$hidden.'<div class="fm2-order-surface"><header>'.$summary.'</header>'.$upload.'<section class="fm2-order-team" aria-labelledby="installers"><div class="fm2-order-section-head"><div><span class="fm2-order-eyebrow">Шаг 2</span><h2 id="installers">Монтажники</h2><p>'.($changing?'Текущий состав выбран заранее. Добавьте или уберите монтажников для версии '.((int)($f['currentVersion']??0)+1).'.':'Выберите состав, указанный в подписанном распоряжении.').'</p></div></div><div class="fm2-order-selection">'.$installers.'</div></section><aside class="fm2-order-engineer"><div><span>Инженер строительного контроля</span><small>Назначен в карточке объекта</small></div>'.$engineerInfo.'</aside><footer class="fm2-order-actions"><a class="shlz-link" href="/pilot/objects/'.$id.'">Отмена</a>'.$uploadAction.'</footer></div>'.$helper.'</form>';
        $body.='<script src="/pilot/assets/picker.js" defer></script>';
        return PilotView::document($user,'Формирование распоряжения','Объекты монтажа',PilotView::breadcrumb([['Объекты монтажа','/pilot/objects'],['Объект монтажа № '.$id,'/pilot/objects/'.$id]],'Распоряжение'),$body);
    }
    public function renderCompatibility(HttpUser $user,array $f):string{return $this->render($user,$f);}
}
